import { useState, useEffect } from 'react'
import { connect } from 'react-redux'
import { PinInputWrapper } from './index.style'
import { CustomText, Container, Button } from '../../../../components'
import PinInput from '../../../../components/PinInput'
import { CORRECT_ICON, PIN_NEW, SMARTPHONE } from '../../../../images'
import SendOtpModalContainer from '../../../../components/SendOtpModalPin/container'
import OtpInput from '../../../../components/PinOtpInput'
import { useUpdateGlobal } from '../../../../state/globalState/hooks/useGlobalContext'
import AuthActions from '../../../../redux/auth/action'
import ErrorActions from '../../../../redux/error/action'
import { useHistory } from 'react-router'
import ShowSnackbar from '../../../../components/ShowNotification'
import { hashString } from '../../../../helpers/hashString'

const {
  validatePin,
  verifyOtp,
  updateOldPin,
  updatePin,
  sendOtp,
  resetAuthStore,
} = AuthActions
const { resetErrorRedux } = ErrorActions

function PinContainer(props) {
  const history = useHistory()
  const {
    validatePin,
    verifyOtp,
    updateOldPin,
    updatePin,
    sendOtp,
    resetAuthStore,
    resetErrorRedux,
  } = props
  const [error, setError] = useState(false)
  const [step, setStep] = useState(0)
  const [pin, setPin] = useState('')
  const [oldPin, setOldPin] = useState('')
  const [otp, setOtp] = useState('')
  const [operationId, setOperationId] = useState('')
  const [otpMedium, setOtpMedium] = useState('sms')
  const [{ agentDetails = {} }] = useUpdateGlobal()

  useEffect(() => {
    if (props.sendOtpStatus.result === 'Success') {
      setOperationId(props.sendOtpStatus.operation_id)
      resetAuthStore(['sendOtpStatus'])
    } else {
      resetAuthStore(['sendOtpStatus'])
    }
  }, [props.sendOtpStatus, operationId, resetAuthStore])

  useEffect(() => {
    if (oldPin && props.validatePinStatus?.auth_token) {
      setStep(1)
      resetAuthStore(['validatePinStatus'])
    } else if (props.validatePinError) {
      if (ShowSnackbar.error) {
        ShowSnackbar.error({
          visible: true,
          text: 'PIN salah',
        })
      }
      setOldPin('') // Clear old PIN input field on wrong PIN
      resetErrorRedux(['VALIDATE_PIN'])
    }
  }, [
    props.validatePinStatus,
    props.validatePinError,
    oldPin,
    resetAuthStore,
    resetErrorRedux,
  ])

  useEffect(() => {
    if (step === 4 && props.sendOtpStatus.result === 'Success') {
      setStep(5)
    } else if (step === 4 && props.sendOtpError) {
      if (ShowSnackbar.error) {
        ShowSnackbar.error({
          visible: true,
          text: 'Tunggu 30 menit, untuk mengganti nomor',
        })
      }
      resetErrorRedux(['SEND_OTP'])
    }
  }, [props.sendOtpStatus, props.sendOtpError, step, resetErrorRedux])

  useEffect(() => {
    if (otp && props.verifyOtpStatus === 'OTP successfully verified') {
      setStep(1)
      resetAuthStore(['verifyOtpStatus'])
    } else if (props.verifyOtpError) {
      if (ShowSnackbar.error) {
        ShowSnackbar.error({
          visible: true,
          text: 'Invalid OTP code, please try again',
        })
      }
      setOtp('') // Clear OTP input field on wrong OTP
      resetErrorRedux(['VERIFY_OTP'])
    }
  }, [
    props.verifyOtpStatus,
    props.verifyOtpError,
    otp,
    resetErrorRedux,
    resetAuthStore,
  ])

  useEffect(() => {
    if (
      (oldPin && props.updateOldPinStatus === 'Pin successfully updated') ||
      (otp && props.updatePinStatus === 'Pin successfully updated')
    ) {
      setStep(3)
      resetAuthStore(['updateOldPinStatus'])
      resetAuthStore(['updatePinStatus'])
    } else if (props.updateOldPinError || props.updatePinError) {
      if (ShowSnackbar.error) {
        ShowSnackbar.error({
          visible: true,
          text: 'Error',
        })
      }
      resetErrorRedux(['UPDATE_OLD_PIN'])
      resetErrorRedux(['UPDATE_PIN'])
    }
  }, [
    props.updateOldPinStatus,
    props.updateOldPinError,
    props.updatePinError,
    props.updatePinStatus,
    otp,
    oldPin,
    resetAuthStore,
    resetErrorRedux,
  ])

  useEffect(() => {
    return () => {
      clearInterval()
    }
  }, [])

  const handleBackButton = () => {
    if (step === 0) {
      history.push('/profile')
    }
    if (step === 1) {
      setStep(0)
    }
    if (step === 2) {
      setStep(1)
    }
    if (step === 4) {
      setStep(0)
    }
    if (step === 5) {
      setStep(4)
    }
  }

  const handlePin = (value) => {
    setPin(value)
    setStep(2)
  }

  const handleCheckOldPin = (value) => {
    const body = {
      phone_no: agentDetails.phone_no,
      pin: hashString(value),
    }
    setOldPin(value)
    validatePin({ payload: body })
  }

  const btnclicked = () => {
    setStep(4)
  }

  const backToProfile = () => {
    history.push('/profile')
  }

  const handleSubmit = (value) => {
    if (value === pin) {
      if (otp) {
        const body = {
          phone_no: agentDetails.phone_no,
          new_pin: hashString(value),
          otp: otp,
          operation_id: operationId,
        }
        updatePin(body)
        // setStep(3)
      } else {
        const body = {
          phone_no: agentDetails.phone_no,
          new_pin: hashString(value),
          old_pin: hashString(oldPin),
        }
        updateOldPin(body)
      }
    } else {
      setError(true)
    }
  }

  const handleSave = () => {
    const body = {
      channel: otpMedium,
      phone_no: agentDetails.phone_no,
    }
    sendOtp(body)
  }

  const submitOtp = (value) => {
    const body = {
      otp: value,
      operation_id: operationId,
    }
    verifyOtp(body)
    setOtp(value)
  }

  return (
    <Container
      title="Ubah PIN"
      showInnerHeader
      displayBackButton={step !== 3}
      onBackClick={handleBackButton}
      hideBottomTabs
    >
      <PinInputWrapper>
        {(step === 0 || step === 1 || step === 2) && (
          <>
            <div className="correct-icon">
              <img src={PIN_NEW} alt="" />
            </div>
            <CustomText
              fontColor="#333333"
              size="14px"
              weight={700}
              textAlign="center"
              top="20px"
              bottom="10px"
            >
              {step === 0
                ? 'Masukkan PIN Lama'
                : step === 1
                  ? 'Masukkan PIN Baru'
                  : 'Konfirmasi PIN Baru'}
            </CustomText>
            <CustomText
              fontColor="#333333"
              size="12px"
              weight={500}
              textAlign="center"
              bottom="8%"
            >
              {step === 0
                ? 'Masukkan 4 digit PIN lama Anda.'
                : step === 1
                  ? 'Masukkan 4 digit PIN baru Anda. Disarankan berbeda dengan PIN lama Anda.'
                  : 'Masukkan kembali 4 digit PIN baru untuk konfirmasi.'}
            </CustomText>
          </>
        )}
        {step === 0 && (
          <>
            <PinInput onComplete={handleCheckOldPin} />
            <div onClick={btnclicked}>
              <CustomText
                textDecoration="underline"
                fontColor="#0078FA"
                size={10}
                weight={600}
                textAlign="center"
                top="5%"
                bottom="8%"
              >
                Lupa PIN Anda?
              </CustomText>
            </div>
          </>
        )}
        {step === 1 && <PinInput onComplete={handlePin} />}
        {step === 2 && (
          <>
            <PinInput
              onComplete={handleSubmit}
              error={error}
              setError={setError}
            />
            {error && (
              <CustomText
                size="12px"
                weight={500}
                textAlign="center"
                top="20px"
                bottom=""
                color="#DC0000"
              >
                PIN tidak sama dengan yang sebelumnya.
              </CustomText>
            )}
          </>
        )}
        {step === 3 && (
          <>
            <div className="correct-icon">
              <img src={CORRECT_ICON} alt="" />
            </div>
            <CustomText
              fontColor="#333333"
              size="14px"
              weight={700}
              textAlign="center"
              top="8%"
              bottom="2%"
            >
              PIN Berhasil Diperbarui
            </CustomText>
            <CustomText
              size="12px"
              weight={500}
              textAlign="center"
              top="5px"
              bottom="60%"
              color="#333333"
            >
              Saatnya memulai perjalanan Anda bersama kami. Bersiap untuk meraih
              komisi dari setiap penjualan asuransi dan berkesempatan
              memenangkan liburan gratis ke luar negeri!
            </CustomText>
            <Button
              onClick={backToProfile}
              className="submit-button"
              textColor="#000000"
            >
              Masuk
            </Button>
          </>
        )}
        {step === 4 && (
          <SendOtpModalContainer
            handleSave={handleSave}
            otpMedium={otpMedium}
            setOtpMedium={setOtpMedium}
          />
        )}
        {step === 5 && (
          <>
            <div className="correct-icon">
              <img src={SMARTPHONE} alt="" />
            </div>
            <CustomText
              fontColor="#333333"
              size="14px"
              weight={700}
              textAlign="center"
              top="4%"
              bottom="3%"
            >
              Kode OTP
            </CustomText>
            <CustomText
              fontColor="#333333"
              size="12px"
              weight={500}
              textAlign="center"
            >
              Masukkan OTP yang terkirim ke nomor ponsel
            </CustomText>
            <CustomText
              fontColor="#333333"
              size="12px"
              weight={700}
              textAlign="center"
              bottom="3%"
            >
              {agentDetails.phone_no}
            </CustomText>
            <OtpInput onComplete={submitOtp} />
          </>
        )}
      </PinInputWrapper>
    </Container>
  )
}

export default connect(
  (state) => ({
    sendOtpLoading: state.Loading.SEND_OTP,
    sendOtpError: state.Error.SEND_OTP,
    sendOtpStatus: state.Auth.sendOtpStatus,

    verifyOtpLoading: state.Loading.VERIFY_OTP,
    verifyOtpError: state.Error.VERIFY_OTP,
    verifyOtpStatus: state.Auth.verifyOtpStatus,

    validatePinLoading: state.Loading.VALIDATE_PIN,
    validatePinError: state.Error.VALIDATE_PIN,
    validatePinStatus: state.Auth.validatePinStatus,

    updatePinLoading: state.Loading.UPDATE_PIN,
    updatePinError: state.Error.UPDATE_PIN,
    updatePinStatus: state.Auth.updatePinStatus,

    updateOldPinLoading: state.Loading.UPDATE_OLD_PIN,
    updateOldPinError: state.Error.UPDATE_OLD_PIN,
    updateOldPinStatus: state.Auth.updateOldPinStatus,
  }),
  {
    validatePin,
    updatePin,
    updateOldPin,
    verifyOtp,
    sendOtp,
    resetAuthStore,
    resetErrorRedux,
  }
)(PinContainer)
